/* Generated by Vite at build time. Cache only public application resources. */
const CACHE = 'kiosco-public-__CACHE_VERSION__';
const ASSETS = __PRECACHE_ASSETS__;
const DEVELOPMENT = __DEVELOPMENT__;
const scope = self.registration.scope;
const offlineURL = new URL('offline.html', scope).href;

self.addEventListener('install', (event) => {
  if (DEVELOPMENT) return;
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(
    ASSETS.map((path) => new URL(path, scope).href),
  )));
  // Updates wait until all existing windows close, preserving unfinished sales.
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    if (DEVELOPMENT) { await self.clients.claim(); return; }
    const keys = await caches.keys();
    await Promise.all(keys.filter((key) => key.startsWith('kiosco-public-') && key !== CACHE)
      .map((key) => caches.delete(key)));
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  if (DEVELOPMENT) return; // Local push testing never intercepts Vite or HMR.
  const { request } = event;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== self.location.origin) return;

  if (request.mode === 'navigate') {
    event.respondWith(fetch(request).catch(async () => {
      const cache = await caches.open(CACHE);
      return (await cache.match(new URL('index.html', scope).href)) || (await cache.match(offlineURL)) || Response.error();
    }));
    return;
  }

  // Never intercept authentication, database calls or arbitrary same-origin APIs.
  if (!ASSETS.some((path) => new URL(path, scope).href === url.href)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    return (await cache.match(request)) || fetch(request);
  })());
});

self.addEventListener('push', (event) => {
  let payload = {};
  try { payload = event.data?.json() || {}; } catch { /* Display a safe fallback. */ }
  if (!payload || typeof payload !== 'object') payload = {};
  const view = ['catalog', 'cash', 'settings'].includes(payload.view) ? payload.view : 'settings';
  const storeId = typeof payload.storeId === 'string' && /^[0-9a-f-]{36}$/i.test(payload.storeId) ? payload.storeId : '';
  event.waitUntil(self.registration.showNotification(
    typeof payload.title === 'string' ? payload.title.slice(0, 100) : 'Kiosco Express', {
      body: typeof payload.body === 'string' ? payload.body.slice(0, 300) : 'Tenés novedades en tu comercio.',
      icon: new URL('icons/icon-192.png', scope).href,
      tag: typeof payload.tag === 'string' ? payload.tag.slice(0, 150) : 'kiosco-notice',
      data: { storeId, view },
    },
  ));
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil((async () => {
    const data = event.notification.data || {};
    const view = ['catalog', 'cash', 'settings'].includes(data.view) ? data.view : 'settings';
    const storeId = typeof data.storeId === 'string' && /^[0-9a-f-]{36}$/i.test(data.storeId) ? data.storeId : '';
    const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    const existing = windows.find(client => client.url.startsWith(scope));
    if (existing) {
      // Never reload an open POS: it may contain an unfinished sale.
      existing.postMessage({ type: 'retail-push-open', storeId, view });
      await existing.focus();
    } else {
      const url = new URL('./', scope);
      if (storeId) url.hash = `push?store=${encodeURIComponent(storeId)}&view=${view}`;
      await self.clients.openWindow(url.href);
    }
  })());
});

// Background Sync is progressive enhancement. The foreground app uses the same
// durable queue on browsers that do not provide it. No refresh token is copied here.
function openRetailDatabase() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('retail-offline-v1', 2);
    request.onupgradeneeded = () => { for (const name of ['accounts', 'meta']) if (!request.result.objectStoreNames.contains(name)) request.result.createObjectStore(name); };
    request.onsuccess = () => resolve(request.result); request.onerror = () => reject(request.error);
  });
}
function readRetailRecord(db, table, key) {
  return new Promise((resolve, reject) => {
    const request = db.transaction(table).objectStore(table).get(key);
    request.onsuccess = () => resolve(request.result); request.onerror = () => reject(request.error);
  });
}
async function syncRetailOutbox() {
  const db = await openRetailDatabase();
  try {
    for (let i = 0; i < 100; i++) {
      const auth = await readRetailRecord(db, 'meta', 'auth');
      if (!auth?.token || !auth.expires || auth.expires * 1000 <= Date.now() + 30000) return;
      const state = await readRetailRecord(db, 'accounts', auth.user);
      const entry = state?.queue?.[0];
      if (!entry || entry.error) return;
      const response = await fetch(`${auth.url}/rest/v1/rpc/retail_sync_operation`, {
        method: 'POST', headers: { 'Content-Type': 'application/json', apikey: auth.key, Authorization: `Bearer ${auth.token}` },
        body: JSON.stringify({ p_operation: entry.operation }),
      });
      if (response.status === 401) return; // Resume after the app refreshes the authenticated session.
      if (response.status >= 500 || response.status === 429) throw new Error('Sync temporarily unavailable');
      const result = await response.json();
      await new Promise((resolve, reject) => {
        const tx = db.transaction('accounts', 'readwrite'); const store = tx.objectStore('accounts');
        const get = store.get(auth.user);
        get.onsuccess = () => {
          const current = get.result; if (!current) return;
          const queued = current.queue.find(q => q.operation.id === entry.operation.id);
          if (!queued) return;
          if (response.ok) {
            current.queue = current.queue.filter(q => q.operation.id !== entry.operation.id);
            current.revision = (Number.isInteger(current.revision) ? current.revision : 0) + 1;
            if (entry.operation.kind === 'sale') for (const [key, value] of Object.entries(current.cache)) {
              if (Array.isArray(value) && JSON.parse(key)[0] === 'sales') current.cache[key] = value.map(sale => sale.id === entry.operation.id ? { ...sale, ticketNumber: result.ticketNumber, syncStatus: 'synced' } : sale);
            }
            if (['close', 'close_details'].includes(entry.operation.kind) && Number.isInteger(result.ticketCount)) for (const [key, value] of Object.entries(current.cache)) {
              const [method, args] = JSON.parse(key);
              if (method === 'shiftTicketCount' && args[0] === entry.operation.shift) current.cache[key] = result.ticketCount;
              if (method === 'shifts' && Array.isArray(value)) value.forEach(shift => { if (shift.id === entry.operation.shift) shift.ticket_count = result.ticketCount; });
            }
          } else queued.error = entry.operation.kind === 'close_details' && result.message === 'Operación no admitida'
            ? 'Actualizá schema.sql en Supabase para guardar el detalle de billetes y reintentá. El cierre sigue guardado en este dispositivo.'
            : result.message || 'Revisá la operación en la app';
          store.put(current, auth.user);
        };
        tx.oncomplete = resolve; tx.onerror = tx.onabort = () => reject(tx.error);
      });
      for (const client of await self.clients.matchAll({ type: 'window', includeUncontrolled: true })) client.postMessage({ type: 'retail-sync-updated' });
      if (!response.ok) return;
    }
    // A bounded batch avoids monopolizing the worker. The browser can continue later.
    if (self.registration.sync) await self.registration.sync.register('retail-outbox');
  } finally { db.close(); }
}
self.addEventListener('sync', event => {
  if (event.tag === 'retail-outbox') event.waitUntil(syncRetailOutbox());
});
